content.text:
            q = S[d]
            if q >= qmax[d]:
                continue
            while True:
                payload = self._result_payload(d, q)
                if payload is None:
                    break
                if not self._send_data(d, (start + q) & MASK24, payload):
                    self._retire()
                    return
                q += 1
                S[d] = q
                if q >= qmax[d]:
                    break
        self.pending_new = False
    self._retire()

def _result_payload(self, d, q):
    prim = self.prim
    if prim == ALLREDUCE:
        if q >= self.K:
            return None
        p = q
    elif prim == REDUCE:
        if d != self.root or q >= self.K:
            return None
        p = q
    elif prim == BCAST:
        if d == self.root or q >= self.K:
            return None
        p = q
    elif prim == BARRIER:
        if q >= 1:
            return None
        p = 0
    elif prim == GATHER:
        if q >= self.qmax[d]:
            return None
        p = q // 3
    else:
        if q >= self.block:
            return None
        p = d * self.block + q
    slot = self.slots.get(p)
    if slot is None or not slot[1]:
        return None
    if prim == GATHER:
        return slot[2][self.rank_of[d][q % 3]]
    return slot[3]

# ------------------------------------------------------------------
# retirement
# ------------------------------------------------------------------
def _retire(self):
    slots = self.slots
    b = self.b
    K = self.K
    prim = self.prim
    A = self.A
    U = self.U
    root = self.root
    block = self.block
    while b < K:
        slot = slots.get(b)
        if slot is None or not slot[1]:
            break
        p = b
        if prim == ALLREDUCE or prim == BCAST:
            ok = True
            for d in range(4):
                if prim == BCAST and d == root:
                    continue
                if A[d] <= p:
                    ok = False
                    break
            if not ok:
                break
        elif prim == REDUCE:
            if A[root] <= p:
                break
        elif prim == BARRIER:
            if not (A[0] >= 1 and A[1] >= 1 and A[2] >= 1 and A[3] >= 1):
                break
        elif prim == GATHER:
            if not (A[0] > 3 * p + 2 and A[1] > 3 * p + 2
                    and A[2] > 3 * p + 2 and A[3] > 3 * p + 2):
                break
        else:
            if A[p // block] <= p % block:
                break
        ok = True
        for r in self.req_list:
            if U[r] <= p:
                ok = False
                break
        if not ok:
            break
        del slots[b]
        b += 1
    self.b = b

# ------------------------------------------------------------------
# event replay
# ------------------------------------------------------------------
def replay(self, events):
    for op in events:
        name = op['op']
        if name == 'data':
            self._ev_data(op)
        elif name == 'train':
            self._ev_train(op)
        elif name == 'ack':
            self._ack_packet(op['rank'], op['upto'] & MASK24)
        elif name == 'wire':
            self.ingress(op['rank'], bytes.fromhex(op['hex']))
        elif name == 'flush':
            self.service()
        elif name == 'retry':
            rank = op['rank']
            self.repeat[rank] = True
            self.service(rank)
        elif name == 'budget':
            self.budget = op['n']
        elif name == 'snap':
            self.snapshot(op['tag'])
        else:
            raise ValueError('unknown operation')

def _payload_for(self, rank, p, seed):
    base = (seed + GOLDEN * (p + 1) + MIX1 * (rank + 1)) & 0xFFFFFFFF
    if self.D == 1:
        return struct.pack('!I', (base + self.words[0]) & 0xFFFFFFFF)
    return self.packD(*[(base + w) & 0xFFFFFFFF for w in self.words])

def _ev_data(self, op):
    rank = op['rank']
    p0 = op['p']
    count = op.get('count', 1)
    step = op.get('step', 1)
    seed = op.get('seed', 0)
    xor = op.get('xor', ())
    start = self.start
    build = self.in_data[rank].build
    if 'values' in op:
        payload = self.packD(*op['values'])
        if xor:
            frame = bytearray(build((start + p0) & MASK24, payload))
            for off, val in xor:
                frame[off] ^= val
            self.ingress(rank, frame)
        else:
            self.ingress_generated_data(rank, p0, payload)
        return
    for i in range(count):
        p = p0 + i * step
        payload = self._payload_for(rank, p, seed)
        if xor:
            frame = bytearray(build((start + p) & MASK24, payload))
            for off, val in xor:
                frame[off] ^= val
            self.ingress(rank, frame)
        else:
            self.ingress_generated_data(rank, p, payload)

def _ev_train(self, op):
    prim = self.prim
    p0 = op['p']
    count = op['count']
    width = op['width']
    ranks = op['ranks']
    reverse = op.get('reverse', False)
